<?php
/**
 * Real-time Progress Monitoring System
 * Provides AJAX endpoints and real-time updates for bulk processing
 */

if (!defined('ABSPATH')) {
    exit;
}

class AutoTag_Progress_Monitor {
    
    /**
     * Constructor
     */
    public function __construct() {
        $this->init_hooks();
    }
    
    /**
     * Initialize hooks
     */
    private function init_hooks() {
        // AJAX hooks for progress monitoring
        add_action('wp_ajax_autotag_get_progress', [$this, 'ajax_get_progress']);
        add_action('wp_ajax_autotag_get_queue_details', [$this, 'ajax_get_queue_details']);
        add_action('wp_ajax_autotag_cancel_queue', [$this, 'ajax_cancel_queue']);
        add_action('wp_ajax_autotag_get_rollback_history', [$this, 'ajax_get_rollback_history']);
        add_action('wp_ajax_autotag_rollback_posts', [$this, 'ajax_rollback_posts']);
        add_action('wp_ajax_autotag_get_processing_reports', [$this, 'ajax_get_processing_reports']);
        add_action('wp_ajax_autotag_generate_report', [$this, 'ajax_generate_report']);
        add_action('wp_ajax_autotag_get_cron_diagnostics', [$this, 'ajax_get_cron_diagnostics']);
        
        // Admin scripts and styles
        add_action('admin_enqueue_scripts', [$this, 'enqueue_monitoring_scripts']);
    }
    
    /**
     * Enqueue monitoring scripts and styles
     */
    public function enqueue_monitoring_scripts($hook) {
        // Only load on Auto-Tag Pro admin pages
        if (strpos($hook, 'auto-tag-pro') === false) {
            return;
        }
        
        wp_enqueue_script(
            'autotag-progress-monitor',
            plugin_dir_url(__FILE__) . '../js/progress-monitor.js',
            ['jquery'],
            '2.0.0',
            true
        );
        
        wp_localize_script('autotag-progress-monitor', 'autotagProgress', [
            'ajax_url' => admin_url('admin-ajax.php'),
            'nonce' => wp_create_nonce('autotag_progress_nonce'),
            'refresh_interval' => 2000, // 2 seconds
            'strings' => [
                'processing' => __('Processing...', 'wp-auto-tag-pro'),
                'completed' => __('Completed', 'wp-auto-tag-pro'),
                'error' => __('Error', 'wp-auto-tag-pro'),
                'cancelled' => __('Cancelled', 'wp-auto-tag-pro'),
                'confirm_cancel' => __('Are you sure you want to cancel this processing queue?', 'wp-auto-tag-pro'),
                'confirm_rollback' => __('Are you sure you want to rollback these posts? This action cannot be undone.', 'wp-auto-tag-pro')
            ]
        ]);
        
        wp_enqueue_style(
            'autotag-progress-monitor',
            plugin_dir_url(__FILE__) . '../css/progress-monitor.css',
            [],
            '2.0.0'
        );
    }
    
    /**
     * AJAX: Get real-time progress for all active queues
     */
    public function ajax_get_progress() {
        check_ajax_referer('autotag_progress_nonce', 'nonce');\n        \n        if (!current_user_can('manage_options')) {\n            wp_die(__('Insufficient permissions', 'wp-auto-tag-pro'));\n        }\n        \n        $bulk_processor = $this->get_bulk_processor();\n        if (!$bulk_processor) {\n            wp_send_json_error('Bulk processor not available');\n        }\n        \n        $progress_data = [];\n        \n        // Check if enhanced processor is available\n        if (method_exists($bulk_processor, 'get_realtime_progress')) {\n            $progress_data = $bulk_processor->get_realtime_progress();\n        } else {\n            // Fallback to basic progress\n            $active_queues = $bulk_processor->get_active_queues();\n            foreach ($active_queues as $queue_id => $queue) {\n                $progress_percentage = ($queue['total_posts'] > 0) ? \n                    ($queue['processed_posts'] / $queue['total_posts']) * 100 : 0;\n                \n                $progress_data[$queue_id] = [\n                    'queue_id' => $queue_id,\n                    'action' => $queue['action'],\n                    'status' => $queue['status'],\n                    'progress_percentage' => round($progress_percentage, 2),\n                    'processed_posts' => $queue['processed_posts'],\n                    'total_posts' => $queue['total_posts'],\n                    'tags_added' => $queue['tags_added'],\n                    'errors' => $queue['errors'],\n                    'elapsed_time' => time() - $queue['start_time'],\n                    'last_update' => $queue['last_update']\n                ];\n            }\n        }\n        \n        wp_send_json_success([\n            'queues' => $progress_data,\n            'timestamp' => time(),\n            'memory_usage' => memory_get_usage(true),\n            'peak_memory' => memory_get_peak_usage(true)\n        ]);\n    }\n    \n    /**\n     * AJAX: Get detailed information for a specific queue\n     */\n    public function ajax_get_queue_details() {\n        check_ajax_referer('autotag_progress_nonce', 'nonce');\n        \n        if (!current_user_can('manage_options')) {\n            wp_die(__('Insufficient permissions', 'wp-auto-tag-pro'));\n        }\n        \n        $queue_id = sanitize_text_field($_POST['queue_id'] ?? '');\n        if (empty($queue_id)) {\n            wp_send_json_error('Invalid queue ID');\n        }\n        \n        $bulk_processor = $this->get_bulk_processor();\n        if (!$bulk_processor) {\n            wp_send_json_error('Bulk processor not available');\n        }\n        \n        $queue = $bulk_processor->get_queue($queue_id);\n        if (!$queue) {\n            wp_send_json_error('Queue not found');\n        }\n        \n        wp_send_json_success($queue);\n    }\n    \n    /**\n     * AJAX: Cancel a processing queue\n     */\n    public function ajax_cancel_queue() {\n        check_ajax_referer('autotag_progress_nonce', 'nonce');\n        \n        if (!current_user_can('manage_options')) {\n            wp_die(__('Insufficient permissions', 'wp-auto-tag-pro'));\n        }\n        \n        $queue_id = sanitize_text_field($_POST['queue_id'] ?? '');\n        if (empty($queue_id)) {\n            wp_send_json_error('Invalid queue ID');\n        }\n        \n        $bulk_processor = $this->get_bulk_processor();\n        if (!$bulk_processor) {\n            wp_send_json_error('Bulk processor not available');\n        }\n        \n        // Cancel the specific queue\n        $queue = $bulk_processor->get_queue($queue_id);\n        if (!$queue) {\n            wp_send_json_error('Queue not found');\n        }\n        \n        // Mark as cancelled and clear scheduled events\n        $queue['status'] = 'cancelled';\n        $queue['cancelled_at'] = time();\n        $queue['cancel_reason'] = 'manual_cancel';\n        $queue['last_update'] = time();\n        \n        // Clear post_ids to save memory\n        unset($queue['post_ids']);\n        \n        set_transient('autotag_bulk_queue_' . $queue_id, $queue, HOUR_IN_SECONDS);\n        wp_clear_scheduled_hook('autotag_process_bulk_batch', [$queue_id]);\n        \n        wp_send_json_success([\n            'message' => __('Queue cancelled successfully', 'wp-auto-tag-pro'),\n            'queue_id' => $queue_id\n        ]);\n    }\n    \n    /**\n     * AJAX: Get rollback history\n     */\n    public function ajax_get_rollback_history() {\n        check_ajax_referer('autotag_progress_nonce', 'nonce');\n        \n        if (!current_user_can('manage_options')) {\n            wp_die(__('Insufficient permissions', 'wp-auto-tag-pro'));\n        }\n        \n        $post_ids = isset($_POST['post_ids']) ? array_map('intval', $_POST['post_ids']) : [];\n        $limit = intval($_POST['limit'] ?? 50);\n        \n        $bulk_processor = $this->get_bulk_processor();\n        if (!$bulk_processor || !method_exists($bulk_processor, 'get_rollback_history')) {\n            wp_send_json_error('Rollback system not available');\n        }\n        \n        $history = $bulk_processor->get_rollback_history($post_ids, $limit);\n        \n        wp_send_json_success([\n            'history' => $history,\n            'total_records' => count($history)\n        ]);\n    }\n    \n    /**\n     * AJAX: Rollback specific posts\n     */\n    public function ajax_rollback_posts() {\n        check_ajax_referer('autotag_progress_nonce', 'nonce');\n        \n        if (!current_user_can('manage_options')) {\n            wp_die(__('Insufficient permissions', 'wp-auto-tag-pro'));\n        }\n        \n        $post_ids = isset($_POST['post_ids']) ? array_map('intval', $_POST['post_ids']) : [];\n        if (empty($post_ids)) {\n            wp_send_json_error('No post IDs provided');\n        }\n        \n        $bulk_processor = $this->get_bulk_processor();\n        if (!$bulk_processor || !method_exists($bulk_processor, 'rollback_posts')) {\n            wp_send_json_error('Rollback system not available');\n        }\n        \n        $rollback_queue_id = $bulk_processor->rollback_posts($post_ids);\n        \n        if (is_wp_error($rollback_queue_id)) {\n            wp_send_json_error($rollback_queue_id->get_error_message());\n        }\n        \n        wp_send_json_success([\n            'message' => __('Rollback process started', 'wp-auto-tag-pro'),\n            'rollback_queue_id' => $rollback_queue_id,\n            'post_count' => count($post_ids)\n        ]);\n    }\n    \n    /**\n     * AJAX: Get processing reports\n     */\n    public function ajax_get_processing_reports() {\n        check_ajax_referer('autotag_progress_nonce', 'nonce');\n        \n        if (!current_user_can('manage_options')) {\n            wp_die(__('Insufficient permissions', 'wp-auto-tag-pro'));\n        }\n        \n        $type = sanitize_text_field($_POST['type'] ?? '');\n        $limit = intval($_POST['limit'] ?? 20);\n        \n        $bulk_processor = $this->get_bulk_processor();\n        if (!$bulk_processor || !method_exists($bulk_processor, 'get_processing_reports')) {\n            wp_send_json_error('Reporting system not available');\n        }\n        \n        $reports = $bulk_processor->get_processing_reports($type, $limit);\n        \n        wp_send_json_success([\n            'reports' => $reports,\n            'total_reports' => count($reports)\n        ]);\n    }\n    \n    /**\n     * AJAX: Generate comprehensive report\n     */\n    public function ajax_generate_report() {\n        check_ajax_referer('autotag_progress_nonce', 'nonce');\n        \n        if (!current_user_can('manage_options')) {\n            wp_die(__('Insufficient permissions', 'wp-auto-tag-pro'));\n        }\n        \n        $queue_id = sanitize_text_field($_POST['queue_id'] ?? '');\n        $options = $_POST['options'] ?? [];\n        \n        $bulk_processor = $this->get_bulk_processor();\n        if (!$bulk_processor || !method_exists($bulk_processor, 'generate_processing_report')) {\n            wp_send_json_error('Reporting system not available');\n        }\n        \n        $report = $bulk_processor->generate_processing_report($queue_id, $options);\n        \n        wp_send_json_success([\n            'message' => __('Report generated successfully', 'wp-auto-tag-pro'),\n            'report' => $report\n        ]);\n    }\n    \n    /**\n     * AJAX: Get WordPress Cron diagnostics\n     */\n    public function ajax_get_cron_diagnostics() {\n        check_ajax_referer('autotag_progress_nonce', 'nonce');\n        \n        if (!current_user_can('manage_options')) {\n            wp_die(__('Insufficient permissions', 'wp-auto-tag-pro'));\n        }\n        \n        $bulk_processor = $this->get_bulk_processor();\n        $diagnostics = [];\n        \n        if ($bulk_processor && method_exists($bulk_processor, 'get_cron_diagnostics')) {\n            $diagnostics = $bulk_processor->get_cron_diagnostics();\n        } else {\n            // Basic diagnostics fallback\n            $diagnostics = [\n                'wp_cron_enabled' => !defined('DISABLE_WP_CRON') || !DISABLE_WP_CRON,\n                'scheduled_events' => $this->get_autotag_scheduled_events(),\n                'server_time' => current_time('mysql'),\n                'utc_time' => gmdate('Y-m-d H:i:s'),\n                'timezone' => get_option('timezone_string') ?: 'UTC'\n            ];\n        }\n        \n        wp_send_json_success($diagnostics);\n    }\n    \n    /**\n     * Get bulk processor instance\n     */\n    private function get_bulk_processor() {\n        if (function_exists('wp_autotag_pro') && wp_autotag_pro()->bulk_processor) {\n            return wp_autotag_pro()->bulk_processor;\n        }\n        \n        // Fallback to creating a new instance\n        if (class_exists('AutoTag_Bulk_Enhanced')) {\n            return new AutoTag_Bulk_Enhanced();\n        } elseif (class_exists('AutoTag_Bulk')) {\n            return new AutoTag_Bulk();\n        }\n        \n        return null;\n    }\n    \n    /**\n     * Get Auto-Tag Pro scheduled events (fallback)\n     */\n    private function get_autotag_scheduled_events() {\n        $events = [];\n        $cron_jobs = wp_get_scheduled_events();\n        \n        foreach ($cron_jobs as $timestamp => $scheduled) {\n            foreach ($scheduled as $hook => $event_data) {\n                if (strpos($hook, 'autotag_') === 0) {\n                    $events[] = [\n                        'hook' => $hook,\n                        'timestamp' => $timestamp,\n                        'time_until' => $timestamp - time(),\n                        'args' => $event_data\n                    ];\n                }\n            }\n        }\n        \n        return $events;\n    }\n    \n    /**\n     * Render progress monitor dashboard\n     */\n    public function render_progress_dashboard() {\n        ?>\n        <div id=\"autotag-progress-dashboard\" class=\"wrap\">\n            <h1><?php _e('Auto-Tag Pro - Processing Monitor', 'wp-auto-tag-pro'); ?></h1>\n            \n            <div class=\"autotag-progress-controls\">\n                <button id=\"refresh-progress\" class=\"button\"><?php _e('Refresh', 'wp-auto-tag-pro'); ?></button>\n                <button id=\"cancel-all-queues\" class=\"button button-secondary\"><?php _e('Cancel All', 'wp-auto-tag-pro'); ?></button>\n                <button id=\"generate-report\" class=\"button button-primary\"><?php _e('Generate Report', 'wp-auto-tag-pro'); ?></button>\n                <span class=\"auto-refresh-toggle\">\n                    <label>\n                        <input type=\"checkbox\" id=\"auto-refresh\" checked> \n                        <?php _e('Auto-refresh', 'wp-auto-tag-pro'); ?>\n                    </label>\n                </span>\n            </div>\n            \n            <div class=\"autotag-progress-summary\">\n                <div class=\"summary-card\">\n                    <h3><?php _e('System Status', 'wp-auto-tag-pro'); ?></h3>\n                    <div id=\"system-status\"></div>\n                </div>\n                \n                <div class=\"summary-card\">\n                    <h3><?php _e('Processing Statistics', 'wp-auto-tag-pro'); ?></h3>\n                    <div id=\"processing-stats\"></div>\n                </div>\n            </div>\n            \n            <div class=\"autotag-progress-queues\">\n                <h2><?php _e('Active Processing Queues', 'wp-auto-tag-pro'); ?></h2>\n                <div id=\"progress-queues-list\"></div>\n            </div>\n            \n            <div class=\"autotag-rollback-section\">\n                <h2><?php _e('Rollback Management', 'wp-auto-tag-pro'); ?></h2>\n                <div id=\"rollback-history\"></div>\n            </div>\n            \n            <div class=\"autotag-reports-section\">\n                <h2><?php _e('Processing Reports', 'wp-auto-tag-pro'); ?></h2>\n                <div id=\"processing-reports\"></div>\n            </div>\n        </div>\n        \n        <script type=\"text/javascript\">\n        jQuery(document).ready(function($) {\n            // Initialize progress monitor\n            window.AutoTagProgressMonitor = new AutoTagProgressMonitor();\n        });\n        </script>\n        <?php\n    }\n    \n    /**\n     * Get processing status summary for dashboard\n     */\n    public function get_dashboard_summary() {\n        $bulk_processor = $this->get_bulk_processor();\n        \n        $summary = [\n            'active_queues' => 0,\n            'total_posts_processing' => 0,\n            'completed_today' => 0,\n            'errors_today' => 0,\n            'rollback_available' => 0,\n            'system_health' => 'good'\n        ];\n        \n        if (!$bulk_processor) {\n            $summary['system_health'] = 'error';\n            return $summary;\n        }\n        \n        // Get basic statistics\n        if (method_exists($bulk_processor, 'get_processing_statistics')) {\n            $stats = $bulk_processor->get_processing_statistics();\n            $summary = array_merge($summary, $stats);\n        } else {\n            $active_queues = $bulk_processor->get_active_queues();\n            $summary['active_queues'] = count($active_queues);\n            \n            foreach ($active_queues as $queue) {\n                $summary['total_posts_processing'] += $queue['total_posts'];\n            }\n        }\n        \n        return $summary;\n    }\n}